func resetState() {
	admin = ""
	bankroll = 0
	reservedLiability = 0
	status = statusIdle
	serverSeedHash = ""
	bets = nil
	roundID = 0
	nonceCounter = 0
	lastResult = -1
	history = nil
	bettingClosesAt = 0
	balances = map[address]int64{}
	lps = nil
	totalShares = 0
	totalDeposits = 0
	accumulatedProfit = 0
